// spiffe_rotator.js — Dynamic In-Memory X.509 SVID Hot-Reload
const tls = require('tls');
const fs = require('fs');

class DynamicTlsContextManager {
    constructor(initialCertPath, initialKeyPath, caPath) {
        this.certPath = initialCertPath;
        this.keyPath = initialKeyPath;
        this.caPath = caPath;
        this.secureContext = this.createContext();
        
        // Watch for atomic filesystem symlink flips generated by SPIRE agent
        fs.watchFile(this.certPath, { interval: 5000 }, () => {
            console.log('[SECURITY] Detected updated SPIFFE SVID on disk. Hot-swapping TLS context...');
            try {
                this.secureContext = this.createContext();
                console.log('[SECURITY] Successfully reloaded internal mTLS SecureContext with zero connection drops.');
            } catch (err) {
                console.error('[SECURITY ERROR] Failed to reload TLS context; preserving current valid keys:', err.message);
            }
        });
    }

    createContext() {
        return tls.createSecureContext({
            cert: fs.readFileSync(this.certPath),
            key: fs.readFileSync(this.keyPath),
            ca: fs.readFileSync(this.caPath),
            minVersion: 'TLSv1.3',
            ciphers: 'TLS_AES_256_GCM_SHA384:TLS_CHACHA20_POLY1305_SHA256'
        });
    }

    // Dynamic SNI and Client Context Callback
    getSecureContext() {
        return this.secureContext;
    }
}

module.exports = { DynamicTlsContextManager };
